# Print keys at top level
def print_keys(d, prefix=''):
    if isinstance(d, dict):
        for k, v in d.items():
            print(f'{prefix}{k}')
            if isinstance(v, dict) and len(v) < 20:
                print_keys(v, prefix + '  ')
    elif isinstance(d, list) and len(d) > 0:
        print(f'{prefix}[list of {len(d)} items]')
        if isinstance(d[0], dict):
            print_keys(d[0], prefix + '  ')

print_keys(data)
"

python3 -c "
import json
with open('/app/resources/treasury_bulletin_1991_09.json', 'r') as f:
    data = json.load(f)

# Search for 'saving' in all text fields
texts = []
def find_saving(d, path=''):
    if isinstance(d, str):
        if 'saving' in d.lower():
            texts.append((path, d[:200]))
    elif isinstance(d, dict):
        for k, v in d.items():
            find_saving(v, f'{path}.{k}')
    elif isinstance(d, list) and len(d) < 50:
        for i, item in enumerate(d):
            find_saving(item, f'{path}[{i}]')

find_saving(data)
for path, text in texts[:10]:
    print(f'{path}: {text}')
"

